# Generated by Descant: acceptance tests.

# frozen_string_literal: true
require "rails_helper"

RSpec.describe "Timekeeping Solid Queue configuration" do
  it "works the timekeeping_relay queue with exactly one dedicated worker of one thread and one process in every environment" do
    rendered = ERB.new(Rails.root.join("config/solid_queue.yml").read).result
    config = YAML.safe_load(rendered, aliases: true)

    # "The Timekeeping relay runs on its own queue and worker with one thread and one process"
    %w[development test production].each do |environment|
      workers = config.fetch(environment).fetch("workers")
      expect(workers.size).to eq(1), "#{environment} must start only the relay worker"
      worker = workers.first
      expect([Array(worker["queues"]), worker["threads"], worker["processes"]])
        .to eq([["timekeeping_relay"], 1, 1]), "#{environment} relay worker settings"
      recurring_classes = Array(config.fetch(environment)["dispatchers"]).flat_map do |dispatcher|
        dispatcher.fetch("recurring_tasks", {}).values.map { |task| task["class"] }
      end
      expect(recurring_classes).to include("RelayJob")
    end
    expect(RelayJob.queue_name).to eq("timekeeping_relay")
  end
end
